// Generates the Swift demo-client list the in-app "Shawcliffe Demos" picker
// reads (DEMO_MODE builds). Single source of truth: ./demo-data.mjs.
// Re-run after changing the client list, then COMMIT the generated file.
//
//   node scripts/gen-ios-demo-list.mjs
//
// See ShawcliffeCustomer/DemoPickerView.swift for the consumer.

import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { CLIENTS, clientId } from './demo-data.mjs'

const HERE = dirname(fileURLToPath(import.meta.url))
const OUT = join(
  HERE, '..', 'platform', 'ios-customer',
  'ShawcliffeCustomer', 'DemoClients.generated.swift',
)

// Swift string-literal escaping: backslash and double-quote. Unicode (curly
// quotes, emoji) is fine verbatim in a UTF-8 Swift source file.
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"')

const rows = CLIENTS.map((c) => {
  const f = (v) => `"${esc(v)}"`
  return `    DemoClient(id: ${f(clientId(c.n))}, slug: ${f(c.slug)}, ` +
    `appName: ${f(c.branding.app_name)}, businessName: ${f(c.business_name)}, ` +
    `tagline: ${f(c.branding.tagline)}, primaryColorHex: ${f(c.branding.primary_color)}),`
}).join('\n')

const swift = `// GENERATED by scripts/gen-ios-demo-list.mjs — do not edit by hand.
// Source of truth: scripts/demo-data.mjs. Re-run the generator to update.

struct DemoClient {
    let id: String
    let slug: String
    let appName: String
    let businessName: String
    let tagline: String
    let primaryColorHex: String
}

let demoClients: [DemoClient] = [
${rows}
]
`

writeFileSync(OUT, swift)
console.log(`Wrote ${CLIENTS.length} demo clients →\n  ${OUT}`)
